import math

def is_perfect_square(n):
    """Check if a number is a perfect square."""
    root = int(math.sqrt(n))
    return n == root * root

def split_into_blocks(digits, block_size):
    """Split the digits into blocks of the given size."""
    return [digits[i:i+block_size] for i in range(0, len(digits), block_size)]

def format_output(blocks):
    """Format the blocks into a string with each block on a new line."""
    return '\n'.join(blocks)

def square_it(digits):
    """Orchestration function to process the input digits."""
    num_digits = len(digits)
    if not is_perfect_square(num_digits):
        return "Not a perfect square!"
    block_size = int(math.sqrt(num_digits))
    blocks = split_into_blocks(digits, block_size)
    return format_output(blocks)

