from datetime import datetime, timedelta

def get_day_of_week(minutes):
    start_time = datetime(2023, 1, 1)  # Start from a fixed date, e.g., January 1, 2023
    current_time = start_time + timedelta(minutes=minutes)
    return current_time.strftime('%A')

def get_time_in_24hr_format(minutes):
    start_time = datetime(2023, 1, 1)  # Start from a fixed date, e.g., January 1, 2023
    current_time = start_time + timedelta(minutes=minutes)
    return current_time.strftime('%H:%M')

def day_and_time(mins):
    day = get_day_of_week(mins)
    time = get_time_in_24hr_format(mins)
    return f'{day} {time}'

from datetime import datetime, timedelta

def get_day_of_week_and_time(minutes):
    # Calculate the current time from Sunday midnight
    current_time = datetime(2000, 1, 2) + timedelta(minutes=minutes)
    # Extract the day of the week and time
    day_of_week = current_time.strftime('%A')
    time = current_time.strftime('%H:%M')
    return f'{day_of_week} {time}'

def day_and_time(mins):
    return get_day_of_week_and_time(mins)

